function secretKey(){const raw=Deno.env.get('SUPABASE_SECRET_KEYS');if(raw){try{const obj=JSON.parse(raw);const value=obj.default??Object.values(obj)[0];if(typeof value==='string'&&value)return value;}catch{}}const legacy=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');if(!legacy)throw new Error('Supabase secret key is unavailable.');return legacy;}
