function authToken(req:Request){const h=req.headers.get('authorization')||'';return h.startsWith('Bearer ')?h.slice(7).trim():'';}
function accountToken(req:Request){return String(req.headers.get('x-gomoku-account-token')||'').trim().slice(0,8192);}
async function verifiedAccount(req:Request,required=false){const raw=accountToken(req);if(!raw){if(required)throw Object.assign(new Error('Sign in with THIEPN Account to continue.'),{status:401});return null;}const res=await fetch(SUPABASE_URL+'/auth/v1/user',{headers:{apikey:secretKey(),Authorization:'Bearer '+raw}});if(!res.ok)throw Object.assign(new Error('THIEPN Account session is invalid or expired.'),{status:401});let user:any=null;try{user=await res.json();}catch{}const userId=cleanUserId(user?.id);if(!userId)throw Object.assign(new Error('THIEPN Account session is invalid or expired.'),{status:401});const [connections,grants,profiles]=await Promise.all([rest('account_app_connections?user_id=eq.'+q(userId)+'&app_slug=eq.gomoku&status=eq.connected&select=user_id,app_slug,status'),rest('account_app_grants?user_id=eq.'+q(userId)+'&app_slug=eq.gomoku&permission_id=eq.identity.basic&status=eq.granted&select=permission_id,status'),rest('leaderboard_profiles?user_id=eq.'+q(userId)+'&select=username')]);if(!Array.isArray(connections)||!connections[0]||!Array.isArray(grants)||!grants[0])throw Object.assign(new Error('Connect Gomoku to your THIEPN Account first.'),{status:403});const username=cleanProfileUsername(Array.isArray(profiles)?profiles[0]?.username:'');return {userId,username:username||null};}
async function readBody(req:Request){const len=Number(req.headers.get('content-length')||0);if(len>32768)throw Object.assign(new Error('Request body is too large.'),{status:413});try{return await req.json();}catch{throw Object.assign(new Error('Invalid JSON body.'),{status:400});}}const nowIso=()=>new Date().toISOString(),expiry=()=>new Date(Date.now()+86400000).toISOString(),q=(v:string)=>encodeURIComponent(v);
async function loadRoom(id:string){const rows=await rest(`gomoku_rooms?id=eq.${q(id)}&select=*`),row=Array.isArray(rows)?rows[0]:null;if(!row)return null;if(new Date(row.expires_at).getTime()<=Date.now()){await rest(`gomoku_rooms?id=eq.${q(id)}`,{method:'DELETE'});return null;}return row;}
const SPECTATOR_TTL_MS=45000,PLAYER_ONLINE_TTL_MS=45000,PLAYER_STALE_TTL_MS=600000;
function cleanViewerId(value:unknown){const out=String(value??'').trim();return /^[A-Za-z0-9_-]{12,96}$/.test(out)?out:'';}
function cleanHistoryToken(value:unknown){const out=String(value??'').trim();if(!/^[A-Za-z0-9_-]{24,128}$/.test(out))throw Object.assign(new Error('Invalid match-history credential.'),{status:422});return out;}
async function historyHash(value:unknown){return sha256('gomoku-history-v1:'+cleanHistoryToken(value));}
function publicMatchPlayer(p:any){const profileUsername=cleanProfileUsername(p?.profileUsername);return {seat:Number(p?.seat)||0,name:cleanName(p?.name),color:Number(p?.color)||0,profileUsername:profileUsername||null,verified:!!profileUsername};}
function makeCompletedMatch(roomId:string,state:any){const game=state?.game||{},result=game.result||game.terminal;if(!result)return null;const players=(Array.isArray(state?.players)?state.players:[]).filter((p:any)=>(Number(p?.seat)===1||Number(p?.seat)===2)&&(Number(p?.color)===1||Number(p?.color)===2));if(players.length<2)return null;const moves=Array.isArray(game.moves)?game.moves.map((m:any)=>({i:Number(m.i),color:Number(m.color)})):[],hashes=[...new Set(players.map((p:any)=>String(p.historyHash||'')).filter((x:string)=>x.length>=20))],black=players.find((p:any)=>Number(p.color)===1),white=players.find((p:any)=>Number(p.color)===2),ranked=state?.mode==='ranked'||state?.ranked===true,tournament=state?.mode==='tournament';if(!hashes.length&&!cleanUserId(black?.userId)&&!cleanUserId(white?.userId))return null;return {room_id:roomId,game_version:Math.max(1,Number(state.gameVersion)||1),round:Math.max(1,Number(state.round)||1),rule:'renju-practice',match_mode:tournament?'tournament':ranked?'ranked':'casual',rated:ranked&&!tournament,started_at:state.roundStartedAt||null,completed_at:nowIso(),winner_color:Number(result.winner)||0,result_reason:String(result.reason||'full'),move_count:moves.length,moves,players:players.map((p:any)=>({...publicMatchPlayer(p),historyHash:String(p.historyHash||'')})),history_hashes:hashes,black_user_id:cleanUserId(black?.userId)||null,white_user_id:cleanUserId(white?.userId)||null};}
async function persistMatchSnapshot(snapshot:any){if(!snapshot)return;await rest('gomoku_matches?on_conflict=room_id,game_version',{method:'POST',body:snapshot,prefer:'resolution=ignore-duplicates,return=minimal'});}
