async function listHistory(req:Request){await enforceRequestLimit(req,'history',120,300);const b:any=await readBody(req),hash=await historyHash(b.historyToken),limit=Math.max(1,Math.min(50,Number(b.limit)||20)),rows=await rest('gomoku_matches?history_hashes=cs.'+q('{'+hash+'}')+'&select=room_id,game_version,round,rule,match_mode,rated,started_at,completed_at,winner_color,result_reason,move_count,players,black_rating_before,black_rating_after,white_rating_before,white_rating_after&order=completed_at.desc&limit='+limit);return json({matches:(Array.isArray(rows)?rows:[]).map((r:any)=>publicMatch(r,hash,false))});}
