function emptyStats(){return {games:0,wins:0,draws:0,losses:0,winRate:0,blackGames:0,blackWins:0,whiteGames:0,whiteWins:0,averageMoves:0,currentStreak:{type:null,count:0},longestWinStreak:0,recentForm:[],opponents:0,firstGameAt:null,lastGameAt:null};}
async function statsForUser(userId:string){const id=cleanUserId(userId);if(!id)return emptyStats();const data=await rest('rpc/gomoku_player_stats',{method:'POST',body:{p_user_id:id}});return data&&typeof data==='object'?data:emptyStats();}
function rankedTier(rating:number,games:number){if(games<1)return 'Unrated';if(rating<1300)return 'Bronze';if(rating<1450)return 'Silver';if(rating<1600)return 'Gold';if(rating<1750)return 'Platinum';if(rating<1900)return 'Diamond';return 'Master';}
async function rankedSummary(userId:string){const id=cleanUserId(userId);if(!id)return {rating:1500,peakRating:1500,games:0,wins:0,draws:0,losses:0,rank:null,provisional:true,lastPlayedAt:null,tier:'Unrated'};const data=await rest('rpc/gomoku_ranked_summary',{method:'POST',body:{p_user_id:id}}),out=data&&typeof data==='object'?data:{};return {...out,tier:rankedTier(Number(out.rating)||1500,Number(out.games)||0)};}
async function rankedLeaderboard(req:Request,url:URL){await enforceRequestLimit(req,'ranked-leaderboard',120,300);const limit=Math.max(1,Math.min(100,Number(url.searchParams.get('limit'))||50)),rows=await rest('rpc/gomoku_ranked_leaderboard',{method:'POST',body:{p_limit:limit}}),items=Array.isArray(rows)?rows:[];return json({players:items.map((x:any)=>({rank:Number(x.rank)||0,username:cleanProfileUsername(x.username),rating:Number(x.rating)||1500,peakRating:Number(x.peakRating)||Number(x.rating)||1500,games:Number(x.games)||0,wins:Number(x.wins)||0,draws:Number(x.draws)||0,losses:Number(x.losses)||0,provisional:x.provisional===true,lastPlayedAt:x.lastPlayedAt||null,tier:rankedTier(Number(x.rating)||1500,Number(x.games)||0)})),generatedAt:nowIso()});}
async function rankedMe(req:Request){await enforceRequestLimit(req,'ranked-me',120,300);const account=await verifiedAccount(req,true);return json({username:account!.username,ranked:await rankedSummary(account!.userId)});}
async function rankedQueue(req:Request){await enforceRequestLimit(req,'ranked-queue',240,300);const account=await verifiedAccount(req,true);if(!account!.username)return fail('Create a shared public player username before entering ranked matchmaking.',409);const b:any=await readBody(req),hash=b.historyToken?await historyHash(b.historyToken):null,result=await rest('rpc/gomoku_try_matchmaking',{method:'POST',body:{p_user_id:account!.userId,p_username:account!.username,p_history_hash:hash}});if(result?.status!=='matched')return json(result);const row=await loadRoom(String(result.roomId||''));if(!row)return fail('Matched room could not be loaded. Re-enter matchmaking.',503);const player=(row.state?.players||[]).find((p:any)=>cleanUserId(p?.userId)===account!.userId);if(!player)return fail('Matched room identity is inconsistent.',500);await touchPlayer(row.id,Number(player.seat));return json({...result,role:'player',color:Number(player.color)||0,state:await stateWithPresence(row,{...player,role:'player'})});}
