function cleanTournamentId(value:unknown){const out=String(value??'').trim().toUpperCase();return /^CUP-[A-Z0-9]{8,16}$/.test(out)?out:'';}
function tournamentRoomId(tournamentId:string,round:number,slot:number,replay:number){const core=tournamentId.replace(/^CUP-/,'').slice(0,10);return ('CUPR-'+core+'-R'+round+'S'+slot+'G'+replay).slice(0,32);}
function cleanSeasonCode(value:unknown){const out=String(value??'').trim().toLowerCase();return /^\d{4}-q[1-4]$/.test(out)?out:'';}
async function currentSeason(){await rest('rpc/gomoku_ensure_current_season',{method:'POST',body:{p_at:nowIso()}}).catch(()=>{});const rows=await rest('gomoku_seasons?status=eq.active&select=id,code,name,status,starts_at,ends_at,completed_at,champion_username,participant_count&order=starts_at.desc&limit=1');return Array.isArray(rows)?rows[0]||null:null;}
function safeSeason(row:any){return row?{code:String(row.code||''),name:String(row.name||''),status:String(row.status||''),startsAt:row.starts_at||null,endsAt:row.ends_at||null,completedAt:row.completed_at||null,champion:cleanProfileUsername(row.champion_username)||null,participantCount:Number(row.participant_count)||0}:null;}
async function seasonStandings(seasonId:string,limit=50){const rows=await rest('gomoku_season_standings?season_id=eq.'+q(seasonId)+'&select=username,games,wins,draws,losses,points,rating_current,rating_delta,last_played_at&order=points.desc,wins.desc,rating_current.desc,updated_at.asc&limit='+Math.max(1,Math.min(100,limit))),items=Array.isArray(rows)?rows:[];return items.map((x:any,i:number)=>({rank:i+1,username:cleanProfileUsername(x.username)||'Player',games:Number(x.games)||0,wins:Number(x.wins)||0,draws:Number(x.draws)||0,losses:Number(x.losses)||0,points:Number(x.points)||0,rating:Number(x.rating_current)||1500,ratingDelta:Number(x.rating_delta)||0,lastPlayedAt:x.last_played_at||null}));}
async function standingForUser(season:any,userId:string){if(!season||!cleanUserId(userId))return null;const rows=await rest('gomoku_season_standings?season_id=eq.'+q(String(season.id))+'&user_id=eq.'+q(userId)+'&select=username,games,wins,draws,losses,points,rating_current,rating_delta,last_played_at'),row=Array.isArray(rows)?rows[0]:null;if(!row)return null;const ahead=await rest('gomoku_season_standings?season_id=eq.'+q(String(season.id))+'&or=(points.gt.'+Number(row.points)+',and(points.eq.'+Number(row.points)+',wins.gt.'+Number(row.wins)+'),and(points.eq.'+Number(row.points)+',wins.eq.'+Number(row.wins)+',rating_current.gt.'+Number(row.rating_current)+'))&select=user_id');return {rank:(Array.isArray(ahead)?ahead.length:0)+1,username:cleanProfileUsername(row.username)||'Player',games:Number(row.games)||0,wins:Number(row.wins)||0,draws:Number(row.draws)||0,losses:Number(row.losses)||0,points:Number(row.points)||0,rating:Number(row.rating_current)||1500,ratingDelta:Number(row.rating_delta)||0,lastPlayedAt:row.last_played_at||null};}
async function seasonBoard(req:Request,url:URL){await enforceRequestLimit(req,'season-board',120,300);const season=await currentSeason();if(!season)return json({season:null,players:[],generatedAt:nowIso()});const limit=Math.max(1,Math.min(100,Number(url.searchParams.get('limit'))||50));return json({season:safeSeason(season),players:await seasonStandings(String(season.id),limit),generatedAt:nowIso()});}
async function listSeasons(req:Request,url:URL){await enforceRequestLimit(req,'seasons-list',90,300);await currentSeason();const limit=Math.max(1,Math.min(20,Number(url.searchParams.get('limit'))||8)),rows=await rest('gomoku_seasons?select=id,code,name,status,starts_at,ends_at,completed_at,champion_username,participant_count&order=starts_at.desc&limit='+limit);return json({seasons:(Array.isArray(rows)?rows:[]).map(safeSeason),generatedAt:nowIso()});}
