function safeCareer(row:any){if(!row)return null;const rankedGames=Number(row.ranked_games)||0,rankedWins=Number(row.ranked_wins)||0,tournamentMatches=Number(row.tournament_matches)||0,tournamentWins=Number(row.tournament_match_wins)||0;return {username:cleanProfileUsername(row.username)||'Player',rankedGames,rankedWins,rankedDraws:Number(row.ranked_draws)||0,rankedLosses:Number(row.ranked_losses)||0,rankedWinRate:rankedGames?Math.round(rankedWins*1000/rankedGames)/10:0,currentRating:Number(row.current_rating)||1500,peakRating:Number(row.peak_rating)||1500,currentRankedWinStreak:Number(row.current_ranked_win_streak)||0,bestRankedWinStreak:Number(row.best_ranked_win_streak)||0,tournamentEntries:Number(row.tournament_entries)||0,tournamentMatches,tournamentMatchWins:tournamentWins,tournamentWinRate:tournamentMatches?Math.round(tournamentWins*1000/tournamentMatches)/10:0,tournamentFinals:Number(row.tournament_finals)||0,tournamentTitles:Number(row.tournament_titles)||0,seasonsPlayed:Number(row.seasons_played)||0,bestSeasonRank:Number(row.best_season_rank)||null,seasonPodiums:Number(row.season_podiums)||0,seasonTitles:Number(row.season_titles)||0,lastCompetitiveAt:row.last_competitive_at||null,updatedAt:row.updated_at||null};}
